function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

for (let lineNum = 0; lineNum < lines.length; lineNum++) {
  const line = lines[lineNum]
  const recordNum = lineNum + 1

  if (mode === 'normalize') {
    const uri = URI.parse(line)
    const normalized = normalizeURI(uri)
    if (normalized.error) {
      fail(`line ${recordNum}: the ${normalized.error} has a truncated percent-encoding`)
    }
    out.push(normalized.toString())
  } else {
    // resolve mode
    const spaceIdx = line.indexOf(' ')
    if (spaceIdx === -1) {
      fail(`line ${recordNum}: expected a base and a reference`)
    }

    const baseStr = line.substring(0, spaceIdx)
    const refStr = line.substring(spaceIdx + 1)

    const base = URI.parse(baseStr)
    if (base.scheme === null) {
      fail(`line ${recordNum}: the base has no scheme`)
    }

    const ref = URI.parse(refStr)

    const resolved = resolveURI(base, ref)
    const normalized = normalizeURI(resolved)
    if (normalized.error) {
      fail(`line ${recordNum}: the ${normalized.error} has a truncated percent-encoding`)
    }
    out.push(normalized.toString())
  }
}

if (out.length > 0) {
  process.stdout.write(out.join('\n') + '\n')
}
